import{_ as n,o as i,c as r,ae as t}from"./chunks/framework.BvHJbMD4.js";const c=JSON.parse('{"title":"Teil 4: Die politische Liebesgeschichte","description":"","frontmatter":{},"headers":[],"relativePath":"drehbuch/teil-4-die-politische-liebesgeschichte.md","filePath":"drehbuch/teil-4-die-politische-liebesgeschichte.md"}'),s={name:"drehbuch/teil-4-die-politische-liebesgeschichte.md"};function a(h,e,d,l,o,g){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="teil-4-die-politische-liebesgeschichte" tabindex="-1">Teil 4: Die politische Liebesgeschichte <a class="header-anchor" href="#teil-4-die-politische-liebesgeschichte" aria-label="Permalink to &quot;Teil 4: Die politische Liebesgeschichte&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Der Regen aus Gold</em></p><p><strong>Besetzung:</strong> Birgit Minichmayr (Heidi Horten), Oliver Masucci (Der Generalsekretär / PR-Berater), August Diehl (Der Investigative Reporter / Ein satirischer Abgeordneter).</p><hr><h2 id="szene-1-das-hinterzimmer-des-glanzes" tabindex="-1">Szene 1: Das Hinterzimmer des Glanzes <a class="header-anchor" href="#szene-1-das-hinterzimmer-des-glanzes" aria-label="Permalink to &quot;Szene 1: Das Hinterzimmer des Glanzes&quot;">​</a></h2><p><strong>Ort:</strong> Ein vergoldetes Separée in einem Wiener Nobel-Café. <strong>Zeit:</strong> Wahljahr 2017.</p><p>Heidi (Birgit Minichmayr) sitzt entspannt im Samtsessel. Vor ihr liegt ein Scheckbuch, das wie eine Reliquie auf dem Tisch thront. Der Generalsekretär (Oliver Masucci) beugt sich ehrfürchtig vor.</p><p><strong>GENERALSEKRETÄR</strong> Wir brauchen... Stabilität, Madame. Und Stabilität kostet in diesen Zeiten. Die Plakate, die Online-Anzeigen... die Berater...</p><p><strong>HEIDI</strong> (lächelt) Ich liebe Stabilität. Helmut pflegte zu sagen: „Geld ist der Kleber, der die Gesellschaft zusammenhält.“ Aber wenn man zu viel Kleber nimmt, sieht man die Fugen nicht mehr.</p><hr><h2 id="szene-2-der-sketch-der-„spenden-stuckelung-neu" tabindex="-1">Szene 2: Der Sketch der „Spenden-Stückelung“ (NEU) <a class="header-anchor" href="#szene-2-der-sketch-der-„spenden-stuckelung-neu" aria-label="Permalink to &quot;Szene 2: Der Sketch der „Spenden-Stückelung“ (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein Büro voller Schredder und Taschenrechner. <strong>Zeit:</strong> Spätnachts.</p><p>Drei Berater in maßgeschneiderten Anzügen (Masucci, Diehl, Minichmayr in Mehrfachrollen) sitzen um einen Berg von 500-Euro-Scheinen. Sie haben eine Schablone vor sich.</p><p><strong>BERATER 1 (Masucci)</strong> Hier haben wir insgesamt 931.000 Euro von Madame. Fast eine Million! Ein prächtiger Brocken. Aber am Stück... am Stück ist er unverdaulich für den Rechnungshof.</p><p><strong>BERATER 2 (Diehl)</strong> Wir brauchen das Skalpell. Wir schneiden es in exakt 49.000-Euro-Häppchen. Nicht 50.000! Bei 50.000 gehen die Sirenen an. Bei 49.000... da herrscht heilige Stille.</p><p><strong>BERATER 3 (Minichmayr)</strong> Es ist wie Pointillismus! 19 Mal 49.000 Euro. Viele kleine Punkte. Wenn man davor steht, sieht man nur lauter nette, diskrete Einzelspenden. Erst wenn man weit weg geht, sieht man... das Imperium.</p><hr><h2 id="szene-3-der-regen-aus-gold-im-parlament-neu" tabindex="-1">Szene 3: Der Regen aus Gold im Parlament (NEU) <a class="header-anchor" href="#szene-3-der-regen-aus-gold-im-parlament-neu" aria-label="Permalink to &quot;Szene 3: Der Regen aus Gold im Parlament (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Der Plenarsaal des österreichischen Nationalrats. <strong>Zeit:</strong> Eine fiktive, surreale Debatte über Transparenz.</p><p>Ein Abgeordneter (August Diehl) hält eine leidenschaftliche Rede über die „Unschuld der Spenderin“. Plötzlich beginnt es von der Decke zu regnen. Aber es ist kein Wasser, sondern goldene Konfetti-Münzen mit Heidis Konterfei. Jede Münze trägt die Prägung „49.000“.</p><p><strong>ABGEORDNETER</strong> (während er die Münzen auffängt) Sehen Sie? Das ist kein Geld! Das ist... Wertschätzung! Das ist bürgerschaftliches Engagement in seiner reinsten, geprägten Form! Wer sind wir, dass wir die Hand beißen, die uns so wunderbar stückelt?</p><p>Die anderen Abgeordneten beginnen, die Münzen mit Regenschirmen aufzufangen, die sie verkehrt herum halten.</p><hr><h2 id="szene-4-das-interview-des-vergessens-neu" tabindex="-1">Szene 4: Das Interview des Vergessens (NEU) <a class="header-anchor" href="#szene-4-das-interview-des-vergessens-neu" aria-label="Permalink to &quot;Szene 4: Das Interview des Vergessens (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Eine Jacht im Mittelmeer. <strong>Zeit:</strong> Gegenwart.</p><p>Heidi wird von einem investigativen Journalisten (August Diehl) interviewt. Der Journalist wirkt erschöpft, Heidi ist strahlend.</p><p><strong>JOURNALIST</strong> Frau Horten, Kritiker sagen, Sie kaufen sich mit Ihren Spenden politischen Einfluss. 931.000 Euro sind kein Pappenstiel.</p><p><strong>HEIDI</strong> (lacht glockenhell) Kaufen? Das ist so ein... kaufmännischer Begriff. Ich nenne es „Ermöglichen“. Ich ermögliche es Politikern, sich auf das Wesentliche zu konzentrieren, ohne sich Sorgen um ihr Budget machen zu müssen. Ist das nicht der Inbegriff von Freiheit?</p><hr><h2 id="szene-5-die-„transparenz-gala-–-die-spitze-der-satire-neu" tabindex="-1">Szene 5: Die „Transparenz-Gala“ – Die Spitze der Satire (NEU) <a class="header-anchor" href="#szene-5-die-„transparenz-gala-–-die-spitze-der-satire-neu" aria-label="Permalink to &quot;Szene 5: Die „Transparenz-Gala“ – Die Spitze der Satire (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein prunkvoller Ballsaal, in dem „Transparenz“ als Thema gefeiert wird. <strong>Zeit:</strong> Ein fiktives Gala-Event.</p><p>Jeder Gast trägt eine Maske aus halbtransparentem Plastik. Man sieht die Gesichter, aber sie sind verzerrt.</p><p><strong>ERZÄHLER (Masucci, Off-Stimme)</strong> Sie feierten die Offenheit, während sie die Türen schlossen. Sie nannten es „neuen Stil“, während sie die alten Rezepte Helmuts verfeinerten. Heidi saß in der Mitte, die Sonne ihres eigenen Systems. Jede 49.000-Euro-Tranche auf ihrem Collier entsprach einer kleinen Aufmerksamkeit an eine politische Sektion.</p><p>Heidi tanzt mit einem Minister. Sie flüstert ihm etwas ins Ohr. Er nickt heftig, als würde er eine göttliche Eingebung empfangen.</p><hr><h2 id="szene-6-der-„rechnungshof-albtraum-neu" tabindex="-1">Szene 6: Der „Rechnungshof-Albtraum“ (NEU) <a class="header-anchor" href="#szene-6-der-„rechnungshof-albtraum-neu" aria-label="Permalink to &quot;Szene 6: Der „Rechnungshof-Albtraum“ (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Ein dunkles Archiv, in dem ein einsamer Prüfer (Oliver Masucci) versucht, die Spendenwege nachzuvollziehen. <strong>Zeit:</strong> Nacht.</p><p>Die Aktenordner beginnen sich von selbst zu bewegen. Zahlen hüpfen von den Seiten und bilden Muster an den Wänden.</p><p><strong>PRÜFER</strong> Es ist ein Labyrinth aus Seide und Gold! Man folgt einer 49.000-Euro-Spende und landet bei einer Reitsport-Veranstaltung in Kärnten. Man folgt dem Reitsport und landet bei einem Kunst-Event in Wien. Und am Ende... am Ende steht immer nur ein Name. Aber der Name ist legal. Er ist so legal, dass es weh tut.</p><p>Er wird von einem Berg aus goldenen „Pünktchen“ verschüttet.</p><hr><h2 id="szene-7-das-finale-–-die-ewigkeit-des-kapitals-neu" tabindex="-1">Szene 7: Das Finale – Die Ewigkeit des Kapitals (NEU) <a class="header-anchor" href="#szene-7-das-finale-–-die-ewigkeit-des-kapitals-neu" aria-label="Permalink to &quot;Szene 7: Das Finale – Die Ewigkeit des Kapitals (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Heidis Mausoleum oder eine moderne Kunstgalerie. <strong>Zeit:</strong> In der nahen Zukunft.</p><p>Wir sehen eine riesige Leinwand. Darauf ist Helmut Horten abgebildet, aber das Bild besteht aus Millionen von kleinen Euro-Symbolen. Heidi tritt davor.</p><p><strong>HEIDI</strong> (zum Publikum) Helmut sagte, das Kapital stirbt nie. Er hatte recht. Es wandelt nur seine Form. Früher waren es Kaufhäuser, heute sind es Parlamente. Früher war es die „Marktbereinigung“, heute ist es die „Politikgestaltung“. Aber der Pointillismus bleibt derselbe.</p><p>Sie drückt auf einen Knopf. Das Bild von Helmut verwandelt sich in das Logo einer politischen Partei und dann wieder zurück.</p><hr><h2 id="szene-8-das-begrabnis-des-schweigens-und-die-angst-in-linz" tabindex="-1">Szene 8: Das Begräbnis des Schweigens (und die Angst in Linz) <a class="header-anchor" href="#szene-8-das-begrabnis-des-schweigens-und-die-angst-in-linz" aria-label="Permalink to &quot;Szene 8: Das Begräbnis des Schweigens (und die Angst in Linz)&quot;">​</a></h2><p><strong>Ort:</strong> Eine exklusive Trauerfeier am Wörthersee. Weißer Marmor, schwarze Schleifen, Champagner-Kühler. <strong>Zeit:</strong> Juni 2022 (Rückblende) / Schnitt zu Februar 2026 (Gegenwart).</p><p>Ein fiktiver ÖVP-Klubobmann „August W.“ (August Diehl) steht am Buffet. Er wirkt nervös, telefoniert ständig. Im Hintergrund sehen wir das prunkvolle Foto der verstorbenen Heidi.</p><p><strong>AUGUST W.</strong> (ins Telefon, flüsternd) Ja, ich weiß, dass der Termin in Linz im März ist! Aber ich kann jetzt nicht über das Finanzamt Braunau reden. Wir beerdigen hier gerade die Mutter aller Spendenlisten! Wenn dieses Erbe nicht... „strukturiert“ wird, dann ist Braunau unser kleinstes Problem.</p><p><strong>PRÜFER / BERATER (Masucci)</strong> (tritt hinzu) August, entspann dich. Heidi hat uns 931.000 Gründe hinterlassen, warum wir unbesiegbar sind. Auch wenn sie jetzt weg ist... die Punkte wirken nach.</p><p><strong>AUGUST W.</strong> (bitter) Die Punkte! In Linz nennen sie es „Amtsmissbrauch“. Ich nenne es „regionale Personalplanung“. Heidi hat uns gezeigt, wie man Millionen unsichtbar macht, und ich schaffe es nicht einmal, einen Bürgermeister in Braunau unterzubringen, ohne dass die WKStA mitschreibt? Das ist das Ende der Ästhetik, sag ich dir!</p><hr><h2 id="szene-9-die-geisterstunde-der-bilanzen-neu" tabindex="-1">Szene 9: Die Geisterstunde der Bilanzen (NEU) <a class="header-anchor" href="#szene-9-die-geisterstunde-der-bilanzen-neu" aria-label="Permalink to &quot;Szene 9: Die Geisterstunde der Bilanzen (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Heidis leeres Schlafzimmer. <strong>Zeit:</strong> Nacht.</p><p>August W. schleicht durch den Raum. Er sucht nicht nach Schmuck, sondern nach weiteren Scheckheften. Plötzlich erscheint der Geist von Heidi (Birgit Minichmayr) im Spiegel.</p><p><strong>HEIDI (GEIST)</strong> August... du bist so... kleinteilig. Du sorgst dich um einen Posten in Oberösterreich? Ich habe ganze Sektionen neu gestrichen. Mit Gold.</p><p><strong>AUGUST W.</strong> (zitternd) Madame, die Zeiten haben sich geändert! Der Rechnungshof hat jetzt Augen! Und Thomas Schmid singt lauter als die Wiener Sängerknaben!</p><p><strong>HEIDI (GEIST)</strong> Dann sing mit, August. Aber sing in 49.000er-Takten. Dann versteht keiner den Text, aber alle lieben die Melodie.</p><hr><h2 id="szene-10-der-letzte-pinselstrich-neu" tabindex="-1">Szene 10: Der letzte Pinselstrich (NEU) <a class="header-anchor" href="#szene-10-der-letzte-pinselstrich-neu" aria-label="Permalink to &quot;Szene 10: Der letzte Pinselstrich (NEU)&quot;">​</a></h2><p><strong>Ort:</strong> Eine leere Bühne. <strong>Zeit:</strong> Jetzt.</p><p>Die drei Schauspieler (Diehl, Masucci, Minichmayr) treten aus ihren Rollen. Sie legen ihre Kostüme ab.</p><p><strong>AUGUST DIEHL</strong> Ist es wahr? <strong>OLIVER MASUCCI</strong> Es ist besser als wahr. Es ist dokumentiert. <strong>BIRGIT MINICHMAYR</strong> Es ist eine Mockumentary. Wir können die Wahrheit sagen, solange wir behaupten, es sei erfunden.</p><p>Sie blicken gemeinsam in die Kamera. Im Hintergrund sehen wir das Logo der Webseite: <em>Das Horten-Mysterium</em>.</p><p><strong>FADE OUT.</strong></p>',67)])])}const p=n(s,[["render",a]]);export{c as __pageData,p as default};
